/* phase-v2-final-legacy-removal-reporting-audit */
(() => {
  'use strict';
  const RELEASE = 'phase-v2-final-legacy-removal-reporting-audit';
  const STORAGE_KEY = 'kcp_admin_yoco_v2_control_centre_state_v1';
  const PAGE_SIZES = [25, 50, 100];
  const TABS = [
    ['overview','Overview','fa-gauge-high',null],
    ['events','Event Inbox','fa-inbox',null],
    ['runs','Processing Runs','fa-gears',null],
    ['sales','Sales','fa-receipt','sales_shadow'],
    ['refunds','Refunds','fa-rotate-left','refunds'],
    ['reconciliation','Reconciliation','fa-scale-balanced','reconciliation'],
    ['manual','Manual Review','fa-user-check','manual_review'],
    ['api','API Health','fa-heart-pulse','api_health'],
    ['dead','Dead Letter','fa-triangle-exclamation','dead_letter'],
    ['modifiers','Modifier Engine','fa-code-compare','modifier_engine'],
    ['configuration','Configuration','fa-sliders',null]
  ];
  const tableConfigs = {
    events: {
      endpoint:'events', title:'Event Inbox', detail:'events', id:'id',
      columns:[['received_at','Received','date'],['workspace_id','Workspace'],['integration_id','Integration'],['event_type','Event type','badge'],['yoco_event_id','Event ID','ref'],['source_entity','Source entity','ref'],['signature_valid','Signature','boolean'],['duplicate_receipts','Duplicate'],['capture_status','Capture','badge'],['queue_status','Queue','badge'],['processing_status','Processing','badge'],['processing_attempts','Attempts'],['next_attempt_at','Next retry','date'],['last_error_message','Last error'],['trace_id','Trace ID','ref']],
      filters:[['eventType','Event type'],['signatureValid','Signature valid',[['','All'],['true','Valid'],['false','Invalid']]],['duplicate','Duplicate',[['','All'],['true','Duplicate'],['false','Unique']]],['captureStatus','Capture status'],['queueStatus','Queue status'],['processingStatus','Processing status'],['integration','Integration']], search:true
    },
    runs: {
      endpoint:'processing-runs', title:'Processing Runs', detail:'processing-runs', id:'id',
      columns:[['started_at','Started','date'],['event_type','Event type','badge'],['source_reference','Source reference','ref'],['workspace_id','Workspace'],['current_step','Current step'],['status','Status','badge'],['attempt_number','Attempt'],['duration_ms','Duration','duration'],['next_retry_at','Next retry','date'],['error_category','Error category','badge'],['trace_id','Trace ID','ref']],
      filters:[['status','Status'],['step','Step'],['errorCategory','Error category'],['attempt','Attempt count'],['integration','Integration']]
    },
    sales: {
      endpoint:'sales', title:'Sales', detail:'sales', id:'source_order',
      columns:[['source_order','Source order','ref'],['sale_time','Sale time','date'],['location_id','Location'],['canonical_status','Canonical status','badge'],['mapping_status','Mapping status','badge'],['legacy_sale_found','Legacy sale found','boolean'],['legacy_stock_movement_count','Legacy stock movements'],['v2_proposal_count','V2 proposals'],['financial_match','Financial match','boolean'],['stock_match','Stock match','boolean'],['comparison_status','Comparison','badge'],['last_compared','Last compared','date']],
      filters:[['status','Comparison status'],['integration','Integration']], search:true
    },
    refunds: {
      endpoint:'refunds', title:'Refunds', detail:'refunds', id:'refund_id',
      columns:[['refund_time','Refund time','date'],['refund_id','Refund ID','ref'],['original_order','Original order','ref'],['refund_type','Refund type'],['gross_refund','Gross refund','money'],['financial_status','Financial','badge'],['inventory_status','Inventory','badge'],['reporting_status','Reporting','badge'],['reconciliation_status','Reconciliation','badge'],['manual_review','Manual review','boolean'],['attempts','Attempts']],
      filters:[['status','Status']], search:true
    },
    manual: {
      endpoint:'manual-reviews', title:'Manual Review', detail:'manual-reviews', id:'id',
      columns:[['created_at','Created','date'],['workspace_id','Workspace'],['review_type','Review type','badge'],['source_reference','Source reference','ref'],['reason_message','Reason'],['age_ms','Age','duration'],['status','Status','badge'],['resolved_by','Assigned or resolved by']],
      filters:[['status','Status'],['reviewType','Review type'],['integration','Integration']], search:true
    },
    reconciliation: {
      endpoint:'reconciliation/runs', title:'Reconciliation Runs', detail:'reconciliation/runs', id:'id',
      columns:[['started_at','Started','date'],['workspace_id','Workspace'],['window_start','Window start','date'],['window_end','Window end','date'],['status','Status','badge'],['orders_examined','Orders examined'],['refunds_examined','Refunds examined'],['missing_events','Missing events'],['mismatches','Mismatches'],['automatic_repairs','Automatic repairs'],['manual_reviews','Manual reviews'],['duration_ms','Duration','duration']],
      filters:[['status','Status'],['integration','Integration']]
    },
    api: {
      endpoint:'api-requests', title:'API Requests', id:'id',
      columns:[['created_at','Time','date'],['workspace_id','Workspace'],['endpoint_name','Endpoint'],['resource_id','Resource','ref'],['response_status','HTTP status','badge'],['duration_ms','Duration','duration'],['cache_status','Cache','badge'],['rate_limited','Rate limited','boolean'],['retry_after_seconds','Retry-After'],['attempt','Attempt'],['error_category','Error category','badge'],['trace_id','Trace ID','ref']],
      filters:[['endpoint','Endpoint'],['httpStatus','HTTP status'],['cache','Cache'],['rateLimited','Rate limited',[['','All'],['true','Yes'],['false','No']]],['errorCategory','Error category'],['integration','Integration']]
    },
    modifiers: {
      endpoint:'modifier-engine', title:'Modifier Engine Diagnostics', id:'id', hideActions:true,
      columns:[['compared_at','Compared','date'],['order','Order','ref'],['line_item','Line item'],['old_resolved_usage','Old resolved usage','usage'],['new_resolved_usage','New resolved usage','usage'],['quantity_difference','Quantity difference','number'],['cost_difference','Cost difference','moneyRaw'],['reason','Reason','badge'],['status','Status','badge']],
      filters:[['status','Comparison status',[['','All'],['MATCH','Matched'],['MISMATCH','Mismatch'],['PENDING','Pending']]]], search:true
    },
    dead: {
      endpoint:'dead-letters', title:'Dead Letter', detail:'events', id:'id',
      columns:[['dead_lettered_at','Dead-lettered at','date'],['workspace_id','Workspace'],['event_type','Event type','badge'],['source_reference','Source reference','ref'],['attempts','Attempts'],['last_step','Last step'],['error_category','Error category','badge'],['last_error','Last error'],['age_ms','Age','duration']],
      filters:[['integration','Integration']]
    }
  };
  const defaultState = { tab:'overview', workspace:'', page:1, perPage:25, polling:false, filters:{ from:daysAgo(7), to:new Date().toISOString().slice(0,10), search:'', integration:'', environment:'', eventType:'', status:'' } };
  let state = loadState();
  let capabilities = null;
  let configuration = null;
  let loadingToken = 0;
  let pollingTimer = null;
  let drawer = null;
  let waitingForWorkspace = false;
  let workspaceSubscriptionInstalled = false;

  function daysAgo(days){ const d=new Date(); d.setDate(d.getDate()-days); return d.toISOString().slice(0,10); }
  function loadState(){ try { return {...defaultState,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'),filters:{...defaultState.filters,...(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}').filters||{})}}; } catch { return structuredClone(defaultState); } }
  function saveState(){ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }
  function esc(v){ if(typeof adminEscapeHtml==='function') return adminEscapeHtml(v); return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function workspaceEntries(){ try { return Object.entries(KCPStore.state.workspaces||{}).map(([id,ws])=>[id,ws?.data?.settings?.siteName||ws?.data?.name||id]).sort((a,b)=>a[1].localeCompare(b[1])); } catch { return []; } }
  function currentWorkspace(){ const items=workspaceEntries(); if(!state.workspace || !items.some(([id])=>id===state.workspace)) state.workspace=items[0]?.[0]||''; return state.workspace; }
  function basePath(){
    const workspaceId=currentWorkspace();
    if(!workspaceId) throw new Error('Workspace data is still loading. Please retry after the admin workspace list appears.');
    return `/api/admin/workspaces/${encodeURIComponent(workspaceId)}/yoco-v2/admin/control-centre`;
  }
  async function api(method,path,body){
    const options={method,headers:{Authorization:`Bearer ${adminToken}`}};
    if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}
    if(method!=='GET') options.headers['Idempotency-Key']=crypto.randomUUID();
    const r=await fetch(`${basePath()}/${path}`.replace(/\/$/,''),options); const p=await r.json().catch(()=>({}));
    if(!r.ok) throw new Error(p.error||p.message||`Request failed (${r.status})`); return p;
  }
  function fmtDate(v){ if(!v) return '—'; const d=new Date(v); return Number.isNaN(d.getTime())?esc(v):new Intl.DateTimeFormat('en-ZA',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Johannesburg'}).format(d); }
  function fmtDuration(v){ const n=Number(v); if(!Number.isFinite(n)) return '—'; if(n<1000)return `${Math.round(n)} ms`; if(n<60000)return `${(n/1000).toFixed(1)} s`; if(n<3600000)return `${Math.round(n/60000)} min`; return `${(n/3600000).toFixed(1)} h`; }
  function fmtMoney(v){ const n=Number(v); return Number.isFinite(n)?new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(Math.abs(n)>100000?n/100:n):'—'; }
  function badge(v){ const s=String(v??'Unknown'); return `<span class="yv2-badge ${esc(s.toLowerCase().replace(/[^a-z0-9]+/g,'_'))}">${esc(s.replaceAll('_',' '))}</span>`; }
  function usageCell(value){ const rows=Array.isArray(value)?value:[]; if(!rows.length)return '<span class="yv2-muted">None</span>'; const parts=rows.slice(0,3).map(row=>{const item=row.ingredientItemId||row.ingredient_item_id||'item',qty=Number(row.quantity||0),location=row.locationId||row.location_id||'';return `${esc(item)}: ${esc(Number.isFinite(qty)?qty.toFixed(4).replace(/\.?0+$/,''):qty)}${location?` @ ${esc(location)}`:''}`;}); return `<div class="yv2-usage" title="${esc(JSON.stringify(rows))}">${parts.map(part=>`<span>${part}</span>`).join('')}${rows.length>3?`<small>+${rows.length-3} more</small>`:''}</div>`; }
  function cell(row,key,type){ const v=row?.[key]; if(type==='date')return fmtDate(v); if(type==='duration')return fmtDuration(v); if(type==='money')return fmtMoney(v); if(type==='moneyRaw'){const n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(n):'—';} if(type==='number'){const n=Number(v);return Number.isFinite(n)?esc(n.toFixed(6).replace(/\.?0+$/,'')):'—';} if(type==='usage')return usageCell(v); if(type==='badge')return badge(v); if(type==='boolean')return v===1||v===true?badge('Yes'):v===0||v===false?badge('No'):'—'; if(type==='ref')return `<div class="yv2-ref" title="${esc(v)}">${esc(v||'—')}</div>`; return esc(v??'—'); }
  function customSelect(id,value,options,label){
    const opts=(options||[]).map(o=>Array.isArray(o)?o:[o,o]); const chosen=opts.find(o=>String(o[0])===String(value))||opts[0]||['','All'];
    return `<div class="yv2-select" data-yv2-select="${esc(id)}"><button type="button" class="yv2-select-trigger" aria-haspopup="listbox" aria-expanded="false" title="${esc(label)}"><span>${esc(chosen[1])}</span><i class="fa-solid fa-chevron-down"></i></button><div class="yv2-select-menu" role="listbox" hidden>${opts.map(([val,text])=>`<button type="button" class="yv2-select-option" role="option" data-value="${esc(val)}" aria-selected="${String(val)===String(value)}">${esc(text)}</button>`).join('')}</div></div>`;
  }
  function bindSelects(root){
    root.querySelectorAll('[data-yv2-select]').forEach(select=>{ const trigger=select.querySelector('.yv2-select-trigger'),menu=select.querySelector('.yv2-select-menu'); trigger.onclick=e=>{e.stopPropagation();document.querySelectorAll('.yv2-select-menu').forEach(m=>{if(m!==menu)m.hidden=true});menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));}; select.querySelectorAll('.yv2-select-option').forEach(opt=>opt.onclick=()=>{ const key=select.dataset.yv2Select; setFilter(key,opt.dataset.value||''); menu.hidden=true; }); });
  }
  function inject(){
    if(document.getElementById('nav-yoco-v2')) return;
    const legacy=document.getElementById('nav-integrations');
    legacy?.insertAdjacentHTML('afterend',`<button onclick="switchTab('yoco-v2')" id="nav-yoco-v2" class="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-xs font-bold uppercase text-slate-500 hover:bg-white/5"><i class="fa-solid fa-wave-square w-5"></i> Yoco V2 Engine</button>`);
    document.getElementById('view-content')?.insertAdjacentHTML('beforeend','<div id="view-yoco-v2" class="tab-view"><div class="yv2-loading"><div class="yv2-skeleton"></div><div class="yv2-skeleton"></div></div></div>');
    const original=window.switchTab||switchTab; window.switchTab=function(tab){ original(tab); if(tab==='yoco-v2'){ document.getElementById('view-title').innerText='Yoco V2 Engine'; init(); } };
    document.addEventListener('click',e=>{ if(!e.target.closest('[data-yv2-select]')) document.querySelectorAll('.yv2-select-menu').forEach(m=>m.hidden=true); });
  }
  async function init(){
    const workspaceId=currentWorkspace();
    if(!workspaceId){ waitingForWorkspace=true; renderWorkspacePending(); installWorkspaceSubscription(); return; }
    waitingForWorkspace=false; saveState(); renderShell();
    try { capabilities=await api('GET','capabilities'); configuration=await api('GET','configuration'); if(!TABS.some(t=>t[0]===state.tab && (!t[3]||capabilities.tabs?.[t[3]]))) state.tab='overview'; renderShell(); await loadTab(); setPolling(); }
    catch(e){ renderFatal(e); }
  }
  function renderWorkspacePending(){
    const root=document.getElementById('view-yoco-v2');
    if(root) root.innerHTML='<div class="yv2-loading"><div class="font-black text-white">Loading workspace registry</div><div class="yv2-muted mt-2">The V2 control centre will open as soon as the admin workspace list is available.</div><div class="yv2-skeleton mt-4"></div></div>';
  }
  function installWorkspaceSubscription(){
    if(workspaceSubscriptionInstalled || typeof KCPStore==='undefined' || typeof KCPStore.subscribe!=='function') return;
    workspaceSubscriptionInstalled=true;
    KCPStore.subscribe((nextState)=>{
      if(!waitingForWorkspace) return;
      if(Object.keys(nextState?.workspaces||{}).length>0) init();
    });
  }
  function renderFatal(e){ const root=document.getElementById('view-yoco-v2'); if(root) root.innerHTML=`<div class="yv2-error"><i class="fa-solid fa-triangle-exclamation text-2xl mb-3"></i><div class="font-black text-white">Yoco V2 control centre unavailable</div><p class="mt-2">${esc(e.message)}</p><button class="yv2-btn mt-4" data-action="retry-init">Retry</button></div>`; root?.querySelector('[data-action=retry-init]')?.addEventListener('click',init); }
  function renderShell(){
    const root=document.getElementById('view-yoco-v2'); if(!root)return; const workspaces=workspaceEntries(); const visibleTabs=TABS.filter(t=>!t[3]||capabilities?.tabs?.[t[3]]!==false);
    const env=configuration?.environment||'Local';
    root.innerHTML=`<div class="yv2-shell"><header class="yv2-header"><div><div class="yv2-title">Yoco V2 Engine</div><div class="yv2-subtitle">Structured operational control centre for V2 webhook capture, queue processing, canonical sales and refunds, rate-gated API requests, reconciliation, and manual review.</div></div><div class="yv2-toolbar"><div class="yv2-banner ${esc(env.toLowerCase())}"><i class="fa-solid fa-circle-nodes"></i><span>Environment</span><strong>${esc(env)}</strong></div><div class="yv2-shadow-lock"><i class="fa-solid fa-shield-halved mr-2"></i>V2 live engine · Canonical effects · Rate-gated API</div></div></header>
      <div class="yv2-toolbar">${customSelect('workspace',state.workspace,workspaces,'Workspace')}<button class="yv2-btn" data-action="refresh"><i class="fa-solid fa-arrows-rotate"></i> Refresh</button><label class="yv2-btn"><input type="checkbox" data-action="poll" ${state.polling?'checked':''}> Safe polling</label><span id="yv2-last-refresh" class="yv2-last-refresh">Not refreshed</span></div>
      <nav class="yv2-tabs" aria-label="Yoco V2 sections">${visibleTabs.map(([id,label,icon])=>`<button class="yv2-tab ${state.tab===id?'active':''}" data-tab="${id}"><i class="fa-solid ${icon} mr-2"></i>${label}</button>`).join('')}</nav>
      <div id="yv2-content"><div class="yv2-loading"><div class="yv2-skeleton"></div><div class="yv2-skeleton"></div></div></div></div>`;
    bindSelects(root); root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.page=1;saveState();renderShell();loadTab();}); root.querySelector('[data-action=refresh]').onclick=()=>loadTab(true); root.querySelector('[data-action=poll]').onchange=e=>{state.polling=e.target.checked;saveState();setPolling();};
  }
  function setPolling(){ clearInterval(pollingTimer); if(state.polling) pollingTimer=setInterval(()=>{ if(document.getElementById('view-yoco-v2')?.classList.contains('active')) loadTab(false,true); },30000); }
  function setFilter(key,value){ if(key==='workspace'){state.workspace=value;capabilities=null;configuration=null;state.page=1;saveState();init();return;} state.filters[key]=value;state.page=1;saveState();loadTab(); }
  function query(extra={}){ const p=new URLSearchParams(); const cfg=tableConfigs[state.tab]; const source={...state.filters,...extra,page:state.page,perPage:state.perPage}; Object.entries(source).forEach(([k,v])=>{if(v!==''&&v!=null)p.set(k,String(v))}); if(cfg && ['runs','api'].includes(state.tab)){if(state.filters.from)p.set('from',new Date(`${state.filters.from}T00:00:00+02:00`).toISOString());if(state.filters.to)p.set('to',new Date(`${state.filters.to}T23:59:59+02:00`).toISOString());} return p.toString(); }
  async function loadTab(manual=false,background=false){
    const token=++loadingToken; const content=document.getElementById('yv2-content'); if(!content)return; if(!background) content.innerHTML='<div class="yv2-loading"><div class="yv2-skeleton"></div><div class="yv2-skeleton"></div><div class="yv2-skeleton"></div></div>';
    try {
      let data; if(state.tab==='overview') data=await api('GET',`overview?${query()}`); else if(state.tab==='configuration'){ const [cfg,loc]=await Promise.all([api('GET','configuration'),api('GET','location-readiness').catch(()=>null)]); data={...cfg,location_readiness:loc}; } else if(state.tab==='api'){ const [health,rows]=await Promise.all([api('GET',`api-health?${query()}`),api('GET',`api-requests?${query()}`)]); data={...rows,health}; } else if(state.tab==='reconciliation'){ const [runs,findings]=await Promise.all([api('GET',`reconciliation/runs?${query()}`),api('GET',`reconciliation/findings?${query()}`)]); data={...runs,findings}; } else data=await api('GET',`${tableConfigs[state.tab].endpoint}?${query()}`);
      if(token!==loadingToken)return; if(state.tab==='overview') renderOverview(data); else if(state.tab==='configuration') renderConfiguration(data); else renderTable(data); const stamp=document.getElementById('yv2-last-refresh'); if(stamp)stamp.textContent=`Last refreshed ${fmtDate(new Date().toISOString())}`; if(manual && typeof showToast==='function')showToast('Yoco V2 data refreshed.','success');
    } catch(e){ if(token===loadingToken) renderError(e); }
  }
  function globalFilters(){
    const eventOptions=[['','All event types'],['sale.completed','Sale completed'],['sale.refunded','Sale refunded'],['payment.succeeded','Payment succeeded'],['refund.created','Refund created']]; const statusOptions=[['','All statuses'],['COMPLETED','Completed'],['PROCESSING','Processing'],['RETRY_SCHEDULED','Waiting for retry'],['MANUAL_REVIEW_REQUIRED','Manual review'],['DEAD_LETTERED','Dead letter']];
    return `<div class="yv2-filterbar"><div class="yv2-control">${customSelect('environment',state.filters.environment||configuration?.environment||'',[[configuration?.environment||'Local',configuration?.environment||'Local']],'Environment')}</div><div class="yv2-control">${customSelect('eventType',state.filters.eventType,eventOptions,'Event type')}</div><div class="yv2-control">${customSelect('status',state.filters.status,statusOptions,'Status')}</div><div class="yv2-control"><input class="yv2-date" type="date" data-filter="from" value="${esc(state.filters.from)}" aria-label="From date"></div><div class="yv2-control"><input class="yv2-date" type="date" data-filter="to" value="${esc(state.filters.to)}" aria-label="To date"></div><div class="yv2-search"><input class="yv2-input" data-filter="search" value="${esc(state.filters.search)}" placeholder="Search order, refund, event or trace ID"></div></div>`;
  }
  function bindFilters(root){ bindSelects(root); root.querySelectorAll('[data-filter]').forEach(input=>{ const event=input.type==='text'?'change':'change'; input.addEventListener(event,()=>setFilter(input.dataset.filter,input.value)); if(input.type==='text') input.addEventListener('keydown',e=>{if(e.key==='Enter')setFilter(input.dataset.filter,input.value)}); }); }
  function renderOverview(data){ const content=document.getElementById('yv2-content'); const labels={webhooks_received:'Webhooks received',unique_events:'Unique events',duplicate_deliveries:'Duplicate deliveries',successfully_processed:'Successfully processed',processing_now:'Processing now',waiting_for_retry:'Waiting for retry',manual_review_required:'Manual review required',permanently_failed:'Permanently failed',dead_lettered:'Dead-lettered',capture_failures:'Capture failures',queue_publication_failures:'Queue publication failures',api_rate_limit_events:'API rate-limit events',reconciliation_findings:'Reconciliation findings'}; const links={webhooks_received:['events',{}],unique_events:['events',{}],duplicate_deliveries:['events',{duplicate:'true'}],successfully_processed:['events',{processingStatus:'COMPLETED'}],processing_now:['events',{processingStatus:'PROCESSING'}],waiting_for_retry:['events',{processingStatus:'RETRY_SCHEDULED'}],manual_review_required:['manual',{status:'OPEN'}],permanently_failed:['dead',{}],dead_lettered:['dead',{}],capture_failures:['events',{captureStatus:'FAILED'}],queue_publication_failures:['events',{queueStatus:'PUBLISH_FAILED'}],api_rate_limit_events:['api',{rateLimited:'true'}],reconciliation_findings:['reconciliation',{}]};
    content.innerHTML=`${globalFilters()}<div class="yv2-grid yv2-kpis mt-4">${Object.entries(labels).map(([k,l])=>`<button class="yv2-kpi" data-kpi="${k}"><div class="yv2-kpi-label">${l}</div><div class="yv2-kpi-value">${esc(data.kpis?.[k]??0)}</div><div class="yv2-kpi-link">Open filtered view →</div></button>`).join('')}</div><div class="yv2-grid yv2-health-grid mt-4">${Object.entries(data.health||{}).map(([name,h])=>`<section class="yv2-panel yv2-health"><div class="yv2-health-head"><div class="yv2-health-name">${esc(name.replaceAll('_',' '))}</div>${badge(h.level)}</div><div class="yv2-health-list">${Object.entries(h).filter(([k])=>k!=='level').map(([k,v])=>`<div class="yv2-health-row"><span>${esc(k.replaceAll('_',' '))}</span><span>${k.includes('duration')?fmtDuration(v):k.includes('rate')&&v!=null?`${esc(v)}%`:k.includes('last_')||k.includes('checkpoint')||k.includes('oldest')?fmtDate(v):esc(v??'—')}</span></div>`).join('')}</div></section>`).join('')}</div>`;
    bindFilters(content); content.querySelectorAll('[data-kpi]').forEach(b=>b.onclick=()=>{ const [tab,filters]=links[b.dataset.kpi]; state.tab=tab;state.filters={...state.filters,...filters};state.page=1;saveState();renderShell();loadTab(); });
  }
  function tableFilters(cfg){ const optionsDefault=[['','All']]; return `<div class="yv2-filterbar">${cfg.filters?.map(([key,label,opts])=>`<div class="yv2-control">${opts?customSelect(key,state.filters[key]||'',opts,label):`<input class="yv2-input" data-filter="${key}" value="${esc(state.filters[key]||'')}" placeholder="${esc(label)}">`}</div>`).join('')||''}${cfg.search?`<div class="yv2-search"><input class="yv2-input" data-filter="search" value="${esc(state.filters.search||'')}" placeholder="Search source reference or trace ID"></div>`:''}<div class="yv2-control"><input class="yv2-date" type="date" data-filter="from" value="${esc(state.filters.from)}" aria-label="From date"></div><div class="yv2-control"><input class="yv2-date" type="date" data-filter="to" value="${esc(state.filters.to)}" aria-label="To date"></div></div>`; }
  function actionButtons(row){
    if(state.tab==='dead') return `<div class="yv2-actions"><button class="yv2-btn" data-row-action="view">Timeline</button><button class="yv2-btn" data-row-action="requeue">Requeue</button><button class="yv2-btn" data-row-action="manual-review">Manual review</button><button class="yv2-btn danger" data-row-action="close">Close</button></div>`;
    const acts=Array.isArray(row.available_actions)?row.available_actions:[]; const buttons=[]; if(tableConfigs[state.tab].detail)buttons.push(`<button class="yv2-btn" data-row-action="view">View</button>`); acts.forEach(a=>buttons.push(`<button class="yv2-btn" data-row-action="${esc(a.action)}" ${a.enabled?'':`disabled title="${esc(a.reason||'Not valid in the current state')}"`}>${esc(a.action.replaceAll('-',' '))}</button>`)); if(state.tab==='manual'&&row.status==='OPEN')buttons.push('<button class="yv2-btn primary" data-row-action="approve">Review</button>'); return `<div class="yv2-actions">${buttons.join('')}</div>`;
  }
  function renderTable(data){ const cfg=tableConfigs[state.tab],content=document.getElementById('yv2-content'); const rows=data.rows||[]; const apiSummary=state.tab==='api'?renderApiSummary(data.health):''; const modifierSummary=state.tab==='modifiers'?renderModifierEngineControl(data):''; const actionsHead=cfg.hideActions?'':'<th>Actions</th>'; const actionsCell=cfg.hideActions?'':row=>`<td>${actionButtons(row)}</td>`; content.innerHTML=`${tableFilters(cfg)}${apiSummary}${modifierSummary}<section class="yv2-panel mt-4"><div class="yv2-panel-head"><div><div class="yv2-panel-title">${cfg.title}</div><div class="yv2-panel-note">Structured engine state · Server-side pagination · Payloads excluded from list queries</div></div>${state.tab==='reconciliation'?'<button class="yv2-btn primary" data-action="run-reconciliation"><i class="fa-solid fa-play"></i> Run selected range</button>':''}</div>${rows.length?`<div class="yv2-table-wrap"><table class="yv2-table"><thead><tr>${cfg.columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}${actionsHead}</tr></thead><tbody>${rows.map((row,index)=>`<tr data-row="${index}">${cfg.columns.map(([key,,type])=>`<td>${cell(row,key,type)}</td>`).join('')}${cfg.hideActions?'':actionsCell(row)}</tr>`).join('')}</tbody></table></div>`:`<div class="yv2-empty"><i class="fa-regular fa-folder-open text-2xl mb-3"></i><div>No modifier comparisons match these filters.</div></div>`}${pagination(data.pagination)}</section>${state.tab==='reconciliation'?renderFindingsPanel(data.findings):''}`;
    bindFilters(content); bindRows(content,rows,cfg); bindFindingActions(content,data.findings?.rows||[]); bindModifierEngineControls(content,data); const run=content.querySelector('[data-action=run-reconciliation]'); if(run)run.onclick=()=>runReconciliation();
  }
  function renderModifierEngineControl(data){ const c=data.control||{},s=data.summary||{},o=data.ownership||{},mode=String(c.mode||'LEGACY_WRITE'),rollbackAt=c.rollback_available_until?Date.parse(c.rollback_available_until):NaN,rollbackAvailable=Number.isFinite(rollbackAt)&&rollbackAt>Date.now(),canCutover=Boolean(capabilities?.permissions?.['yoco_v2.cutover']),ready=Boolean(s.ready_for_live); return `<section class="yv2-panel yv2-modifier-control mt-4"><div class="yv2-panel-head"><div><div class="yv2-panel-title">Parallel observation and cutover</div><div class="yv2-panel-note">The comparison engine never writes stock. The authoritative writer is controlled by SALE_STOCK ownership, preventing double deductions.</div></div><div class="yv2-mode">${badge(mode)}</div></div><div class="yv2-grid yv2-kpis yv2-modifier-kpis">${[['Mode',mode],['Authoritative writer',o.authoritative_writer||'Unknown'],['Comparisons',s.comparisons||0],['Matches',s.matches||0],['Mismatches',s.mismatches||0],['Pending',s.pending||0],['Last compared',s.last_compared_at?fmtDate(s.last_compared_at):'—']].map(([label,value])=>`<div class="yv2-kpi"><div class="yv2-kpi-label">${esc(label)}</div><div class="yv2-kpi-value yv2-kpi-value-small">${esc(value)}</div></div>`).join('')}</div><div class="yv2-cutover-status ${ready?'ready':'blocked'}"><i class="fa-solid ${ready?'fa-circle-check':'fa-circle-exclamation'}"></i><div><strong>${ready?'Ready for live cutover':'Live cutover blocked'}</strong><span>${ready?'Observation contains no mismatches or pending comparisons and V2 owns SALE_STOCK.':'Resolve mismatches and pending comparisons, and confirm V2 SALE_STOCK ownership.'}</span></div></div><div class="yv2-control-actions"><button class="yv2-btn" data-modifier-mode="OBSERVE" ${!canCutover||mode==='OBSERVE'?'disabled':''}><i class="fa-solid fa-binoculars"></i> Start observation</button><button class="yv2-btn primary" data-modifier-mode="LIVE" ${!canCutover||mode==='LIVE'||!ready?'disabled':''}><i class="fa-solid fa-power-off"></i> Enable new engine</button><button class="yv2-btn danger" data-modifier-mode="ROLLED_BACK" ${!canCutover||mode!=='LIVE'||!rollbackAvailable?'disabled':''}><i class="fa-solid fa-rotate-left"></i> Roll back</button></div>${c.observation_started_at?`<div class="yv2-control-audit">Observation started ${fmtDate(c.observation_started_at)}${c.cutover_at?` · Cut over ${fmtDate(c.cutover_at)}`:''}${c.rollback_available_until?` · Rollback until ${fmtDate(c.rollback_available_until)}`:''}</div>`:''}</section>`; }
  function bindModifierEngineControls(root,data){ root.querySelectorAll('[data-modifier-mode]').forEach(button=>button.onclick=()=>changeModifierEngineMode(button.dataset.modifierMode,data)); }
  async function changeModifierEngineMode(mode,data){ const labels={OBSERVE:'start modifier observation',LIVE:'enable the new modifier engine',ROLLED_BACK:'roll back the modifier engine'}; const reason=prompt(`Reason to ${labels[mode]||'change modifier mode'}:`,mode==='OBSERVE'?'Controlled workspace observation period.':mode==='LIVE'?'Observation is stable with no unexplained differences.':'Temporary rollback after modifier cutover.'); if(reason===null)return; const warning=mode==='LIVE'?'This enables the new modifier mode for the workspace. SALE_STOCK ownership remains the single authoritative stock writer.':mode==='ROLLED_BACK'?'This uses the temporary rollback control and is available only inside the recorded rollback window.':'The new engine will calculate and compare expected usage without creating a second stock writer.'; if(!confirm(`${labels[mode]||'Change modifier mode'}?

${warning}`))return; try{await api('POST','modifier-engine/control',{mode,reason,confirmed:true,rollbackHours:72});showToast?.('Modifier engine control updated.','success');loadTab(true);}catch(e){showToast?.(e.message,'error');} }
  function renderFindingsPanel(data){ const rows=data?.rows||[]; return `<section class="yv2-panel mt-4"><div class="yv2-panel-head"><div><div class="yv2-panel-title">Reconciliation Findings</div><div class="yv2-panel-note">Each repair is idempotent and independently audited.</div></div></div>${rows.length?`<div class="yv2-table-wrap"><table class="yv2-table"><thead><tr><th>Created</th><th>Severity</th><th>Finding type</th><th>Source</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-finding-row="${i}"><td>${fmtDate(r.created_at)}</td><td>${badge(r.severity)}</td><td>${badge(r.finding_type)}</td><td><div class="yv2-ref">${esc(r.source_entity_id||'—')}</div></td><td>${badge(r.status)}</td><td><div class="yv2-actions"><button class="yv2-btn" data-finding-action="retry">Retry finding</button><button class="yv2-btn" data-finding-action="refetch">Refetch source</button><button class="yv2-btn" data-finding-action="rerun-resolver">Re-run resolver</button><button class="yv2-btn" data-finding-action="rerun-comparison">Re-run comparison</button><button class="yv2-btn" data-finding-action="manual-review">Manual review</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="yv2-empty">No unresolved findings in this selection.</div>'}</section>`; }
  function bindFindingActions(root,rows){ root.querySelectorAll('[data-finding-row]').forEach(tr=>tr.querySelectorAll('[data-finding-action]').forEach(button=>button.onclick=async()=>{ const row=rows[Number(tr.dataset.findingRow)],action=button.dataset.findingAction; const reason=prompt(`Reason for ${action}:`,'Administrator action from reconciliation finding.'); if(reason===null)return; if(!confirm(`${action.replaceAll('-',' ')} for ${row.source_entity_id||row.id}?\n\nThe action is idempotent and cannot create live effects.`))return; try{await api('POST',`reconciliation/findings/${encodeURIComponent(row.id)}/${action}`,{confirmed:true,reason});showToast?.('Reconciliation action accepted.','success');loadTab(true);}catch(e){showToast?.(e.message,'error');} })); }
  function renderApiSummary(health){ const s=health?.summary||{}; return `<div class="yv2-grid yv2-kpis mt-4">${[['requests','Requests'],['success_rate','Success rate'],['cache_hits','Cache hits'],['cache_misses','Cache misses'],['responses_429','429 responses'],['responses_401_403','401/403 responses'],['timeouts','Timeouts'],['responses_5xx','5xx responses'],['average_duration_ms','Average duration']].map(([k,l])=>`<div class="yv2-kpi"><div class="yv2-kpi-label">${l}</div><div class="yv2-kpi-value">${k==='average_duration_ms'?fmtDuration(s[k]):k==='success_rate'&&s[k]!=null?`${esc(s[k])}%`:esc(s[k]??0)}</div></div>`).join('')}</div>`; }
  function pagination(p={page:1,perPage:25,total:0,totalPages:1}){ return `<div class="yv2-pagination"><div class="yv2-page-meta">${esc(p.total||0)} records · Page ${esc(p.page||1)} of ${esc(p.totalPages||1)}</div><div class="yv2-page-actions">${customSelect('perPage',state.perPage,PAGE_SIZES.map(n=>[n,`${n} per page`]),'Rows per page')}<button class="yv2-btn" data-page="prev" ${p.page<=1?'disabled':''}>Previous</button><button class="yv2-btn" data-page="next" ${p.page>=p.totalPages?'disabled':''}>Next</button></div></div>`; }
  function bindRows(root,rows,cfg){ bindSelects(root); root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page+=b.dataset.page==='next'?1:-1;saveState();loadTab();}); root.querySelectorAll('tr[data-row]').forEach(tr=>tr.querySelectorAll('[data-row-action]').forEach(btn=>btn.onclick=()=>handleRowAction(rows[Number(tr.dataset.row)],btn.dataset.rowAction,cfg))); }
  async function handleRowAction(row,action,cfg){
    if(action==='view'||action==='approve') return openDetail(cfg.detail||'events',row[cfg.id],action==='approve');
    const id=row[cfg.id]; const route=state.tab==='dead'?`dead-letters/${encodeURIComponent(id)}/${action}`:`events/${encodeURIComponent(id)}/${action}`; const reason=prompt(`Reason for ${action}:`,'Administrator requested this action.'); if(reason===null)return; if(!confirm(`${action.replaceAll('-',' ')} ${row.source_reference||row.yoco_event_id||id}?\n\nThis action is idempotent and uses the canonical V2 engine.`))return;
    try{await api('POST',route,{confirmed:true,reason});showToast?.(`Yoco V2 ${action} queued.`,'success');loadTab(true);}catch(e){showToast?.(e.message,'error');}
  }
  async function runReconciliation(){ const reason=prompt('Reason for reconciliation:','Admin selected date-range reconciliation.'); if(reason===null)return; const from=new Date(`${state.filters.from}T00:00:00+02:00`).toISOString(),to=new Date(`${state.filters.to}T23:59:59+02:00`).toISOString(); if(!confirm(`Run reconciliation from ${state.filters.from} to ${state.filters.to}?\n\nLive effects are applied only for full replay actions and remain idempotent.`))return; try{await api('POST','reconciliation/run',{window_start:from,window_end:to,confirmed:true,reason});showToast?.('Reconciliation started.','success');loadTab(true);}catch(e){showToast?.(e.message,'error');} }
  async function openDetail(resource,id,approval=false){
    showDrawer('Loading structured detail…','<div class="yv2-loading"><div class="yv2-skeleton"></div><div class="yv2-skeleton"></div></div>');
    try{const data=await api('GET',`${resource}/${encodeURIComponent(id)}`); renderDetail(resource,id,data,approval);}catch(e){setDrawerBody(`<div class="yv2-error">${esc(e.message)}</div>`);}
  }
  function showDrawer(title,body){ closeDrawer(); document.body.insertAdjacentHTML('beforeend',`<div class="yv2-drawer-backdrop" data-yv2-close></div><aside class="yv2-drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="yv2-drawer-head"><div><div class="yv2-drawer-title">${esc(title)}</div><div class="yv2-panel-note">Structured Yoco V2 engine record</div></div><button class="yv2-btn" data-yv2-close aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><div id="yv2-drawer-body" class="yv2-drawer-body">${body}</div></aside>`); drawer=true; document.querySelectorAll('[data-yv2-close]').forEach(x=>x.onclick=closeDrawer); document.querySelector('.yv2-drawer [data-yv2-close]')?.focus(); }
  function closeDrawer(){ document.querySelector('.yv2-drawer')?.remove();document.querySelector('.yv2-drawer-backdrop')?.remove();drawer=null; }
  function setDrawerBody(html){ const b=document.getElementById('yv2-drawer-body');if(b)b.innerHTML=html; }
  function detailGrid(obj){ return `<div class="yv2-detail-grid">${Object.entries(obj||{}).filter(([,v])=>typeof v!=='object').map(([k,v])=>`<div class="yv2-detail-item"><div class="yv2-detail-label">${esc(k.replaceAll('_',' '))}</div><div class="yv2-detail-value">${k.includes('_at')||k.includes('time')?fmtDate(v):esc(v??'—')}</div></div>`).join('')}</div>`; }
  function jsonSection(title,obj,open=false){ return `<details class="yv2-section" ${open?'open':''}><summary><h4>${esc(title)}</h4></summary><div class="yv2-section-body"><div class="yv2-json">${esc(JSON.stringify(obj??null,null,2))}</div></div></details>`; }
  function fmtCents(v){ const n=Number(v&&typeof v==='object'?v.amount:v); return Number.isFinite(n)?new Intl.NumberFormat('en-ZA',{style:'currency',currency:(v&&v.currency)||'ZAR'}).format(n/100):'—'; }
  function summaryCards(pairs){ const cells=(pairs||[]).filter(Boolean).map(([l,v])=>`<div class="yv2-sumcard"><div class="yv2-sumlabel">${esc(l)}</div><div class="yv2-sumval">${v??'—'}</div></div>`).join(''); return cells?`<div class="yv2-sumgrid">${cells}</div>`:''; }
  function linesTable(columns,rows){ const list=Array.isArray(rows)?rows:[]; if(!list.length)return '<div class="yv2-section-body yv2-muted">None.</div>'; return `<div class="yv2-lines-wrap"><table class="yv2-lines"><thead><tr>${columns.map(c=>`<th class="${c[2]?'num':''}">${esc(c[0])}</th>`).join('')}</tr></thead><tbody>${list.map(row=>`<tr>${columns.map(c=>`<td class="${c[2]?'num':''}">${c[1](row)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
  function readableSection(title,inner){ return `<section class="yv2-section"><h4>${esc(title)}</h4>${inner}</section>`; }
  function rawGroup(sections){ const body=(sections||[]).filter(Boolean).join(''); return body?`<details class="yv2-rawgroup"><summary><i class="fa-solid fa-code mr-1"></i>Raw data (advanced)</summary><div class="yv2-rawgroup-body">${body}</div></details>`:''; }
  function renderDetail(resource,id,data,approval){
    let html=''; if(resource==='events'){ html+=`<section class="yv2-section"><h4>Summary</h4><div class="yv2-section-body">${detailGrid(data.summary)}</div></section><section class="yv2-section"><h4>Source references</h4><div class="yv2-section-body">${detailGrid(data.source_references)}</div></section><section class="yv2-section"><h4>Webhook verification</h4><div class="yv2-section-body">${detailGrid(data.webhook_verification)}</div></section><section class="yv2-section"><h4>Processing timeline</h4><div class="yv2-section-body"><div class="yv2-timeline">${(data.timeline||[]).map(t=>`<div class="yv2-timeline-item"><div class="yv2-timeline-time">${fmtDate(t.created_at)} · Attempt ${esc(t.attempt_number??'—')}</div><div class="yv2-timeline-step">${esc(t.step)} · ${esc(t.status)}</div><div class="yv2-timeline-message">${esc(t.message||'')}</div></div>`).join('')||'<div class="yv2-muted">No timeline entries.</div>'}</div></div></section>`; if(data.payload_access)html+=jsonSection('Raw payload (redacted)',data.raw_payload); else html+=`<section class="yv2-section"><h4>Raw payload</h4><div class="yv2-section-body yv2-muted">Permission yoco_v2.view_payload is required.</div></section>`; html+=jsonSection('Redacted headers',data.headers)+jsonSection('Errors',data.errors)+jsonSection('Related records',data.related_records); }
    else if(resource==='processing-runs'){ html+=`<section class="yv2-section"><h4>Processing run</h4><div class="yv2-section-body">${detailGrid(data.run)}</div></section>`+jsonSection('All attempts',data.attempts,true)+jsonSection('Step transitions',data.timeline,true)+jsonSection('Linked API requests',data.api_requests)+jsonSection('Linked event',data.event); }
    else if(resource==='sales'){ html+=v2ActionSection(data.available_actions,resource,id)+jsonSection('Canonical sale',data.canonical_sale,true)+jsonSection('Historical pre-V2 evidence',data.legacy_effects,true)+jsonSection('V2 shadow proposal',data.v2_shadow_proposal,true)+jsonSection('Differences',data.differences,true); }
    else if(resource==='refunds'){
      const fs=data.financial_summary||{}; const statusCards=Object.entries(data.independent_statuses||{}).map(([k,v])=>[k.replaceAll('_',' '),badge(v)]);
      html+=readableSection('Refund summary',summaryCards([['Refund type',esc(data.refund_type||fs.refund_behavior||fs.refund_type||'—')],fs.gross_amount!=null?['Gross',fmtMoney(fs.gross_amount)]:null,fs.net_amount!=null?['Net',fmtMoney(fs.net_amount)]:null,fs.tax_amount!=null?['VAT',fmtMoney(fs.tax_amount)]:null,['Currency',esc(fs.currency||'ZAR')],...statusCards]));
      html+=readableSection('Original order lines',linesTable([['Item',l=>esc(l.name||l.item||l.source_name||l.source_line||l.source_original_line_id||'—')],['Sold',l=>esc(l.quantity_sold??'—'),true],['Refunded',l=>esc(l.quantity_previously_refunded??0),true],['Remaining',l=>esc(l.remaining_refundable_quantity??'—'),true]],data.original_order_lines));
      html+=readableSection('Returned lines',linesTable([['Item',l=>esc(l.source_name||l.name||'—')],['Qty',l=>esc(l.quantity??'—'),true],['Gross',l=>fmtMoney(l.gross_amount),true],['Method',l=>esc(l.resolution_method||'—')],['Mapped',l=>badge(l.mapping_status||'—')]],data.returned_lines));
      html+=v2ActionSection(data.available_actions,resource,id);
      html+=rawGroup([jsonSection('Financial summary',data.financial_summary),jsonSection('Original order lines',data.original_order_lines),jsonSection('Returned lines',data.returned_lines),jsonSection('Historical pre-V2 outcome',data.legacy_outcome),jsonSection('V2 shadow outcome',data.v2_shadow_outcome)]);
    }
    else if(resource==='manual-reviews'){
      const r=data.review||{}; const rf=r.refund_financials||{};
      html+=readableSection('Manual review',summaryCards([['Type',badge(r.review_type||'—')],['Status',badge(r.status||'—')],['Reason',esc(r.reason_message||r.reason_code||'—')],['Created',esc(fmtDate(r.created_at))],rf.gross_amount!=null?['Gross',fmtMoney(rf.gross_amount)]:null,rf.net_amount!=null?['Net',fmtMoney(rf.net_amount)]:null,rf.tax_amount!=null?['VAT',fmtMoney(rf.tax_amount)]:null]));
      html+=readableSection('Available source lines',linesTable([['Item',l=>esc(l.name||l.item||l.source_original_line_id||'—')],['Qty',l=>esc(l.quantity??'—'),true],['Unit',l=>fmtCents(l.unit_price),true],['Total',l=>fmtCents(l.total_price),true]],r.available_source_lines));
      if(approval&&r.status==='OPEN')html+=manualAllocationForm(id,data);
      html+=rawGroup([jsonSection('Manual review',data.review),jsonSection('Canonical refund event',data.domain_event)]);
    }
    else if(resource==='reconciliation/runs'){ html+=jsonSection('Run',data.run,true)+jsonSection('Coverage and checkpoints',{checkpoint_before:data.checkpoint_before,checkpoint_after:data.checkpoint_after,coverage_window:data.coverage_window,overlap_window:data.overlap_window,rate_limit_pauses:data.rate_limit_pauses,repairs_performed:data.repairs_performed},true)+jsonSection('Findings by severity',data.findings_by_severity)+jsonSection('Findings',data.findings,true); }
    else html+=jsonSection('Structured detail',data,true); setDrawerBody(html); bindDetailActions();
  }
  function v2ActionSection(actions,resource,id){ const rows=Array.isArray(actions)?actions:[]; if(!rows.length)return ''; return `<section class="yv2-section"><h4>V2-only actions</h4><div class="yv2-section-body"><div class="yv2-shadow-lock mb-3">These actions rebuild canonical V2 data. Full replay actions apply idempotent live effects; proposal-only actions remain diagnostic.</div><div class="yv2-actions">${rows.map(a=>`<button class="yv2-btn" data-v2-action="${esc(a.action)}" data-v2-resource="${esc(resource)}" data-v2-id="${esc(id)}" ${a.enabled===false?'disabled':''}>${esc(a.action.replaceAll('-',' '))}</button>`).join('')}</div></div></section>`; }
  function manualAllocationForm(id,data){ const lines=data.review?.available_source_lines||data.domain_event?.payload?.original_order_lines||[]; return `<section class="yv2-section"><h4>Approve refund line allocation</h4><div class="yv2-section-body"><div class="yv2-shadow-lock mb-3">Approving saves the allocation and applies the controlled live refund stock return, subject to the active ownership / pre-launch cutover gates.</div><div id="yv2-allocation-lines">${(Array.isArray(lines)?lines:[]).map((line,i)=>`<div class="yv2-detail-item mb-2"><div class="yv2-detail-value">${esc(line.item||line.name||line.source_original_line_id||`Line ${i+1}`)}</div><div class="yv2-muted text-xs">Sold ${esc(line.quantity_sold??'—')} · Already refunded ${esc(line.quantity_previously_refunded??0)} · Remaining ${esc(line.remaining_refundable_quantity??line.quantity_sold??0)}</div><input class="yv2-input mt-2" type="number" min="0" max="${esc(line.remaining_refundable_quantity??line.quantity_sold??0)}" step="0.001" data-allocation-line="${esc(line.source_original_line_id||line.source_line||line.id||'')}" value="0"></div>`).join('')||'<div class="yv2-muted">No allocatable source lines are available.</div>'}</div><label class="block text-xs text-slate-300 mt-3"><input type="checkbox" id="yv2-financial-ack"> Acknowledge any documented financial difference</label><button class="yv2-btn primary mt-3" data-approve-review="${esc(id)}">Validate and approve allocation</button></div></section>`; }
  function bindDetailActions(){
    document.querySelectorAll('[data-v2-action], [data-v2-action]').forEach(button=>button.onclick=async()=>{ const action=button.dataset.v2Action || button.dataset.shadowAction,resource=button.dataset.v2Resource || button.dataset.shadowResource,id=button.dataset.v2Id || button.dataset.shadowId; const reason=prompt(`Reason for ${action}:`,'Administrator requested a canonical V2 rebuild.'); if(reason===null)return; if(!confirm(`${action.replaceAll('-',' ')} ${id}?\n\nLive effects are applied only for full replay actions and remain idempotent.`))return; try{await api('POST',`${resource}/${encodeURIComponent(id)}/${action}`,{confirmed:true,reason});showToast?.(`${action} queued through the V2 engine.`,'success');closeDrawer();loadTab(true);}catch(e){showToast?.(e.message,'error');} });
    const button=document.querySelector('[data-approve-review]'); if(button)button.onclick=async()=>{ const allocation=[...document.querySelectorAll('[data-allocation-line]')].map(i=>({source_original_line_id:i.dataset.allocationLine,quantity:Number(i.value)})).filter(x=>x.source_original_line_id&&x.quantity>0); if(!allocation.length)return showToast?.('Allocate at least one positive quantity.','error'); if(!confirm('Approve this manual allocation and apply the controlled live refund re-resolution?'))return; try{await api('POST',`manual-reviews/${encodeURIComponent(button.dataset.approveReview)}/approve`,{allocation,acknowledge_financial_difference:document.getElementById('yv2-financial-ack')?.checked,confirmed:true,reason:'Administrator approved manual refund allocation.'});showToast?.('Manual allocation approved; controlled re-resolution queued.','success');closeDrawer();loadTab(true);}catch(e){showToast?.(e.message,'error');} };
  }
  function renderConfiguration(data){ configuration=data; const content=document.getElementById('yv2-content'); const bool=(v)=>v?badge('Enabled'):badge('Disabled'); content.innerHTML=`<div class="yv2-shadow-lock"><i class="fa-solid fa-lock mr-2"></i>V2 is the only production Yoco execution engine. Effect ownership must remain V2; use pause and reconciliation controls for safe operations.</div><div class="yv2-grid yv2-config-grid"><div class="yv2-config-card"><h4>Capture</h4><div class="yv2-config-row"><span>Capture enabled</span>${bool(data.capture?.enabled)}</div><div class="yv2-config-row"><span>Queue enabled</span>${bool(data.queue?.enabled)}</div><div class="yv2-config-row"><span>Admin enabled</span>${bool(data.admin?.enabled)}</div></div><div class="yv2-config-card"><h4>V2 processing</h4><div class="yv2-config-row"><span>V2 sales</span>${bool(data.shadow_processing?.sales)}</div><div class="yv2-config-row"><span>V2 refunds</span>${bool(data.shadow_processing?.refunds)}</div></div><div class="yv2-config-card"><h4>Live effects</h4>${Object.entries(data.live_effects||{}).filter(([k])=>!k.includes('configured')&&k!=='read_only').map(([k,v])=>`<div class="yv2-config-row"><span>${esc(k.replaceAll('_',' '))}</span>${bool(v)}</div>`).join('')}</div><div class="yv2-config-card"><h4>Effect ownership</h4>${(data.effect_ownership||[]).map(r=>`<div class="yv2-config-row"><span>${esc(r.effect_type)}</span>${badge(r.engine_version||r.owner||'UNASSIGNED')}</div>`).join('')||'<div class="yv2-muted">No ownership rows.</div>'}</div><div class="yv2-config-card"><h4>Integration state</h4>${Object.entries(data.integration_state||{}).map(([k,v])=>`<div class="yv2-config-row"><span>${esc(k.replaceAll('_',' '))}</span><span>${k.startsWith('last_')?fmtDate(v):esc(v??'—')}</span></div>`).join('')}</div><div class="yv2-config-card"><h4>Cutover</h4><div class="yv2-config-row"><span>Permission exists</span>${bool(data.cutover?.permission_exists)}</div><div class="yv2-config-row"><span>Usable</span>${bool(data.cutover?.usable)}</div><p class="yv2-muted text-xs mt-2">${esc(data.cutover?.reason)}</p></div>${locationReadinessCard(data.location_readiness)}</div>`; }
  function locationReadinessCard(lr){ if(!lr||lr.ok===false) return '<div class="yv2-config-card"><h4>Location mappings</h4><div class="yv2-muted">Readiness unavailable.</div></div>'; const unmapped=lr.unmapped_locations||[]; const head=unmapped.length?`<div class="yv2-shadow-lock mb-3">${esc(unmapped.length)} Yoco location${unmapped.length===1?'':'s'} seen in orders ${unmapped.length===1?'is':'are'} not mapped to an active KCP location — their stock will not move until mapped.</div>`:`<div class="yv2-config-row"><span>Status</span>${badge('All Yoco locations mapped')}</div>`; return `<div class="yv2-config-card"><h4>Location mappings</h4>${head}<div class="yv2-config-row"><span>Yoco locations seen</span><span>${esc(lr.seen_count??0)}</span></div><div class="yv2-config-row"><span>Active Yoco mappings</span><span>${esc(lr.mapped_count??0)}</span></div><div class="yv2-config-row"><span>Unmapped</span><span>${esc(lr.unmapped_count??0)}</span></div>${unmapped.map(u=>`<div class="yv2-config-row"><span class="yv2-ref" title="${esc(u.yoco_location_id)}">${esc(u.yoco_location_id)}</span><span>${esc(u.event_count)} orders${u.mapping_missing_count?` · ${esc(u.mapping_missing_count)} blocked`:''}</span></div>`).join('')}</div>`; }
  function renderError(e){ const c=document.getElementById('yv2-content');if(c)c.innerHTML=`<div class="yv2-error"><i class="fa-solid fa-triangle-exclamation text-2xl mb-3"></i><div>${esc(e.message)}</div><button class="yv2-btn mt-4" data-action="retry">Retry</button></div>`;c?.querySelector('[data-action=retry]')?.addEventListener('click',()=>loadTab(true)); }
  window.KCPYocoV2Admin={release:RELEASE,openEvent:(id)=>{state.tab='events';saveState();switchTab('yoco-v2');setTimeout(()=>openDetail('events',id),0);},search:(reference,workspaceId)=>{if(workspaceId)state.workspace=workspaceId;state.tab='events';state.filters.search=String(reference||'');state.page=1;saveState();switchTab('yoco-v2');setTimeout(()=>{renderShell();loadTab();},0);},refresh:()=>loadTab(true)};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',inject);else inject();
})();
